export function getAgentBySlug(slug: string): AgentData | undefined {
  return ALL_AGENTS.find(a => a.slug === slug);
}

export function filterAgents(agents: AgentData[], cat: string, query: string): AgentData[] {
  const q = query.toLowerCase();
  let filtered = agents.filter(a => {
    const matchQ = !q || a.name.toLowerCase().includes(q) || a.ticker.toLowerCase().includes(q) || a.cat.toLowerCase().includes(q);
    if (!matchQ) return false;
    if (cat === 'All')      return true;
    if (cat === 'Trending') return parseFloat(a.change) > 5;
    if (cat === 'New')      return a.isNew === true;
    if (cat === 'Volume')   return a.vol > 0;
    return true;
  });
  if (cat === 'Trending') filtered = filtered.sort((a,b) => parseFloat(b.change) - parseFloat(a.change));
  if (cat === 'Volume')   filtered = filtered.sort((a,b) => b.vol - a.vol);
  return filtered;
}
